const listPurchaseOrders = `-- name: ListPurchaseOrders :many
SELECT po.id, po.number, po.status, po.project_id, po.supplier_id, po.rfq_id, po.total_amount, po.currency,
       po.expected_delivery_date, po.created_at, po.sent_at, p.name AS project_name, s.name AS supplier_name,
       (SELECT count(*) FROM purchase_order_lines l WHERE l.purchase_order_id = po.id)::int AS line_count,
       (SELECT count(*) FROM purchase_order_lines l WHERE l.purchase_order_id = po.id AND l.quantity_remaining = 0)::int AS lines_received
  FROM purchase_orders po
  JOIN projects p  ON p.id = po.project_id
  JOIN suppliers s ON s.id = po.supplier_id
 WHERE po.organization_id = $1
   AND ($2::boolean
        OR p.manager_id = $3
        OR EXISTS (SELECT 1 FROM project_members m WHERE m.project_id = p.id AND m.user_id = $3))
   AND ($4::uuid  IS NULL OR po.project_id = $4)
   AND ($5::uuid IS NULL OR po.supplier_id = $5)
   AND ($6::text      IS NULL OR po.status = $6)
 ORDER BY po.created_at DESC, po.id DESC
 LIMIT 200
`

type ListPurchaseOrdersParams struct {
	OrgID       uuid.UUID  `json:"org_id"`
	AllProjects bool       `json:"all_projects"`
	UserID      uuid.UUID  `json:"user_id"`
	ProjectID   *uuid.UUID `json:"project_id"`
	SupplierID  *uuid.UUID `json:"supplier_id"`
	Status      *string    `json:"status"`
}

type ListPurchaseOrdersRow struct {
	ID                   uuid.UUID   `json:"id"`
	Number               int32       `json:"number"`
	Status               string      `json:"status"`
	ProjectID            uuid.UUID   `json:"project_id"`
	SupplierID           uuid.UUID   `json:"supplier_id"`
	RfqID                *uuid.UUID  `json:"rfq_id"`
	TotalAmount          int64       `json:"total_amount"`
	Currency             string      `json:"currency"`
	ExpectedDeliveryDate *civil.Date `json:"expected_delivery_date"`
	CreatedAt            time.Time   `json:"created_at"`
	SentAt               *time.Time  `json:"sent_at"`
	ProjectName          string      `json:"project_name"`
	SupplierName         string      `json:"supplier_name"`
	LineCount            int32       `json:"line_count"`
	LinesReceived        int32       `json:"lines_received"`
}

func (q *Queries) ListPurchaseOrders(ctx context.Context, arg ListPurchaseOrdersParams) ([]ListPurchaseOrdersRow, error) {
	rows, err := q.db.Query(ctx, listPurchaseOrders,
		arg.OrgID,
		arg.AllProjects,
		arg.UserID,
		arg.ProjectID,
		arg.SupplierID,
		arg.Status,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPurchaseOrdersRow{}
	for rows.Next() {
		var i ListPurchaseOrdersRow
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.Status,
			&i.ProjectID,
			&i.SupplierID,
			&i.RfqID,
			&i.TotalAmount,
			&i.Currency,
			&i.ExpectedDeliveryDate,
			&i.CreatedAt,
			&i.SentAt,
			&i.ProjectName,
			&i.SupplierName,
			&i.LineCount,
			&i.LinesReceived,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

